{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Kalkulator Matriks Risiko 5x5 K3 Online",
  "url": "https://wahanatotalita.com/tools/risk-matrix/",
  "description": "Aplikasi evaluasi matriks risiko 5x5 standar ISO 31000 dan HIRARC dengan fitur pembuatan dan pencetakan dokumen Risk Register K3.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Apa itu Matriks Risiko 5x5 dalam K3?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Matriks Risiko 5x5 adalah alat visual penilaian risiko yang memetakan probabilitas atau peluang terjadinya suatu bahaya (Likelihood skala 1-5) dengan tingkat keparahan konsekuensi dampaknya (Consequence skala 1-5) untuk menghasilkan skor risiko total (1 hingga 25), yang terbagi dalam kategori Rendah (Low), Sedang (Medium), Tinggi (High), hingga Ekstrem (Extreme)."
      }
    },
    {
      "@type": "Question",
      "name": "Apa yang dimaksud dengan prinsip ALARP (As Low As Reasonably Practicable)?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ALARP adalah prinsip penilaian keselamatan di mana risiko harus diturunkan sampai ke level terendah yang dapat dicapai secara praktis, mempertimbangkan perbandingan biaya finansial, waktu, dan upaya teknis terhadap manfaat penurunan risiko yang diperoleh."
      }
    },
    {
      "@type": "Question",
      "name": "Kapan suatu pekerjaan harus segera dihentikan berdasarkan Matriks Risiko?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Pekerjaan wajib segera dihentikan seketika (Stop Work Authority) jika penilaian risiko awal (Initial Risk) menghasilkan level Ekstrem / Kritis (skor 15-25). Pekerjaan sama sekali tidak boleh dilanjutkan sampai tindakan pengendalian fisik tingkat tinggi diterapkan dan risiko sisa (Residual Risk) turun ke level Sedang atau Rendah."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.rm-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 58px 0 44px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.rm-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.rm-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.7rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.rm-hero h1 span { color: var(--orange); }
.rm-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 20px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* WORKSPACE LAYOUT */
.rm-wrapper { padding: 40px 0 60px; }
.rm-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 32px;
  align-items: start;
}
@media (max-width: 992px) {
  .rm-grid { grid-template-columns: 1fr; }
}

.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* 5x5 MATRIX GRID */
.matrix-container {
  display: grid;
  grid-template-columns: 80px repeat(5, 1fr);
  gap: 6px;
  margin: 16px 0 24px;
}
.matrix-cell {
  aspect-ratio: 1.25;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-weight: 800;
  font-family: 'Lexend', sans-serif;
  cursor: pointer;
  transition: all 0.2s;
  position: relative;
  user-select: none;
  font-size: 1.1rem;
}
.matrix-cell small { font-size: 0.68rem; font-weight: 600; opacity: 0.9; }
.matrix-cell:hover {
  transform: scale(1.05);
  box-shadow: 0 6px 16px rgba(0,0,0,0.15);
  z-index: 2;
}
.matrix-cell.selected {
  outline: 3px solid #000;
  box-shadow: 0 0 0 4px #fff, 0 8px 20px rgba(0,0,0,0.25);
  transform: scale(1.08);
  z-index: 3;
}

/* Risk Colors */
.cell-low { background: #86EFAC; color: #14532D; }
.cell-med { background: #FDE047; color: #713F12; }
.cell-high { background: #FDBA74; color: #7C2D12; }
.cell-ext { background: #FCA5A5; color: #7F1D1D; }

.matrix-header-y {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--slate-600);
  text-align: center;
  line-height: 1.2;
}
.matrix-header-x {
  grid-column: 2 / span 5;
  text-align: center;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--navy);
  padding: 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* CONTROLS SLIDERS / SELECTORS */
.control-row { margin-bottom: 20px; }
.control-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 8px;
}
.select-styled {
  width: 100%;
  padding: 10px 14px;
  border: 1.5px solid var(--slate-200);
  border-radius: var(--radius-md);
  font-size: 0.92rem;
  color: var(--slate-900);
  background: #fff;
}
.select-styled:focus {
  outline: none;
  border-color: var(--orange);
}

/* RESULT DETAILS */
.risk-score-display {
  background: var(--slate-50);
  border: 2px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  margin-bottom: 24px;
}
.score-badge {
  display: inline-block;
  font-family: 'Lexend', sans-serif;
  font-size: 2.8rem;
  font-weight: 900;
  line-height: 1;
  padding: 12px 28px;
  border-radius: var(--radius-md);
  margin-bottom: 12px;
}
.score-cat {
  font-family: 'Lexend', sans-serif;
  font-size: 1.3rem;
  font-weight: 800;
  margin-bottom: 8px;
}
.score-timeframe {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--slate-700);
  background: rgba(0,0,0,0.04);
  padding: 6px 14px;
  border-radius: 999px;
  display: inline-block;
}

/* RISK REGISTER TABLE */
.register-table-wrapper {
  overflow-x: auto;
  margin-top: 16px;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
}
.reg-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
.reg-table th {
  background: var(--navy);
  color: #fff;
  padding: 10px 12px;
  text-align: left;
  font-size: 0.82rem;
}
.reg-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--slate-200);
  background: #fff;
}
.reg-table tr:hover td { background: var(--slate-50); }

/* EDITORIAL ARTICLE */
.editorial-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}

/* FAQ */
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; }

